const APLUS_AI_DB_V1_P6_COMPREHENSION_QUESTION_BANK = [
{id:'P6-COMP-0001',type:'literal',skill:'retrieval',passage:'Maya reached the community garden at seven in the morning. She carried a basket of seedlings and a small watering can.',question:'What did Maya carry?',options:['A basket of seedlings and a watering can','A box of tools and gloves','A bag of books and a bottle','A basket of fruit and a shovel'],answer:'A basket of seedlings and a watering can',explanation:'Both items are stated directly in the passage.',difficulty:1},
{id:'P6-COMP-0002',type:'literal',skill:'retrieval',passage:'The school library closed at four o’clock because the staff had to attend a training session.',question:'Why did the library close at four o’clock?',options:['The students had gone home.','The staff had a training session.','The books had to be moved.','The building needed repairs.'],answer:'The staff had a training session.',explanation:'The reason is stated directly.',difficulty:1},
{id:'P6-COMP-0003',type:'inference',skill:'inferencing',passage:'Jon stared at the dark sky and hurried to bring the clothes from the balcony indoors. Moments later, heavy drops began to fall.',question:'Why did Jon bring the clothes indoors?',options:['He expected rain.','He wanted to wash them.','He was going to iron them.','He needed the balcony for a game.'],answer:'He expected rain.',explanation:'The dark sky and the falling rain show that Jon anticipated rain.',difficulty:2},
{id:'P6-COMP-0004',type:'inference',skill:'inferencing',passage:'Ella checked the map twice before leaving the station. She kept looking at the street signs as she walked.',question:'What can we infer about Ella?',options:['She knew the area very well.','She was unsure of the route.','She was looking for a restaurant.','She had lost her bag.'],answer:'She was unsure of the route.',explanation:'Checking the map and signs repeatedly suggests uncertainty about the route.',difficulty:2},
{id:'P6-COMP-0005',type:'vocabulary',skill:'word in context',passage:'The puppy was timid at first, hiding behind the chair whenever a visitor entered. After several days, it began approaching people.',question:'What does timid mean in the passage?',options:['Shy and easily frightened','Hungry and restless','Noisy and playful','Angry and aggressive'],answer:'Shy and easily frightened',explanation:'The puppy hides from visitors, which shows that it is timid.',difficulty:2},
{id:'P6-COMP-0006',type:'main_idea',skill:'main idea',passage:'A class began collecting used paper from every classroom. At the end of each week, the paper was sent for recycling. After three months, the class had greatly reduced the amount of paper thrown away.',question:'What is the main idea?',options:['The class reduced paper waste through recycling.','The class wanted more paper for art.','The school stopped using paper completely.','The class collected books every week.'],answer:'The class reduced paper waste through recycling.',explanation:'The whole passage focuses on the recycling effort and its result.',difficulty:2},
{id:'P6-COMP-0007',type:'sequence',skill:'sequencing',passage:'First, Amir washed the seeds. Next, he placed them in a tray of soil. Finally, he watered the soil and put the tray near the window.',question:'What did Amir do immediately before watering the soil?',options:['He washed the seeds.','He placed the seeds in soil.','He moved the tray outside.','He closed the window.'],answer:'He placed the seeds in soil.',explanation:'The sequence states that placing the seeds came before watering.',difficulty:2},
{id:'P6-COMP-0008',type:'cause_effect',skill:'cause and effect',passage:'The path became slippery after several hours of rain. For safety, the organisers moved the race to the sports hall.',question:'Why was the race moved?',options:['The sports hall was empty.','The path became slippery.','The runners arrived late.','The race was too short.'],answer:'The path became slippery.',explanation:'The slippery path created the safety concern.',difficulty:2},
{id:'P6-COMP-0009',type:'author_intent',skill:'purpose',passage:'Remember to bring a reusable bottle tomorrow. One small change can help reduce the amount of plastic waste we create.',question:'What is the writer mainly trying to do?',options:['Persuade readers to reduce plastic waste','Describe how bottles are manufactured','Explain why tomorrow is important','Compare different sports bottles'],answer:'Persuade readers to reduce plastic waste',explanation:'The writer gives a suggestion and a reason to encourage action.',difficulty:2},
{id:'P6-COMP-0010',type:'reference',skill:'reference words',passage:'The children planted flowers beside the fence. They watered them every afternoon.',question:'What does them refer to?',options:['The children','The fence','The flowers','The afternoons'],answer:'The flowers',explanation:'Them refers to the flowers that were planted.',difficulty:1},
{id:'P6-COMP-0011',type:'comparison',skill:'compare information',passage:'Lina cycles to school because it takes twelve minutes. Her brother takes the bus, which usually takes twenty minutes but is more comfortable on rainy days.',question:'Which statement is true?',options:['Cycling usually takes longer.','The bus is always faster.','Cycling takes less time.','Lina takes the bus on sunny days.'],answer:'Cycling takes less time.',explanation:'The passage gives twelve minutes for cycling and twenty for the bus.',difficulty:2},
{id:'P6-COMP-0012',type:'inference',skill:'character inference',passage:'When the younger pupils could not understand the instructions, Kai knelt beside them and explained each step patiently.',question:'Which quality does Kai show?',options:['Impatience','Consideration','Carelessness','Dishonesty'],answer:'Consideration',explanation:'Helping patiently shows consideration for others.',difficulty:2},
{id:'P6-COMP-0013',type:'tone',skill:'tone',passage:'What a wonderful surprise! The entire class cheered when their project was selected for the exhibition.',question:'What is the tone?',options:['Joyful','Angry','Fearful','Bored'],answer:'Joyful',explanation:'Wonderful surprise and cheering indicate happiness.',difficulty:1},
{id:'P6-COMP-0014',type:'inference',skill:'predicting',passage:'The wind became stronger and the organisers began folding the outdoor tables. Dark clouds gathered above the field.',question:'What was most likely to happen next?',options:['The organisers would prepare for rain or move indoors.','The organisers would start a swimming lesson.','The wind would suddenly disappear.','The tables would be used for a picnic.'],answer:'The organisers would prepare for rain or move indoors.',explanation:'The weather signs and safety action suggest an approaching storm.',difficulty:3},
{id:'P6-COMP-0015',type:'vocabulary',skill:'word in context',passage:'The old bridge was fragile, so visitors were told not to cross it.',question:'What does fragile mean?',options:['Easily damaged or broken','Very wide and strong','Newly painted','Difficult to find'],answer:'Easily damaged or broken',explanation:'The warning not to cross indicates that the bridge could be damaged or unsafe.',difficulty:2},
{id:'P6-COMP-0016',type:'main_idea',skill:'summary',passage:'For one month, a pupil kept a notebook of the birds seen near his block. He recorded their colours, sizes and habits. At the end of the month, he noticed that different birds appeared at different times of day.',question:'Which is the best summary?',options:['A pupil observed and recorded birds and discovered patterns in their behaviour.','A pupil bought many colourful birds.','Birds only appear near blocks in the morning.','The pupil built a large bird cage.'],answer:'A pupil observed and recorded birds and discovered patterns in their behaviour.',explanation:'The answer covers the main actions and finding without unnecessary detail.',difficulty:3},
{id:'P6-COMP-0017',type:'cause_effect',skill:'cause and effect',passage:'Nadia forgot to charge her tablet before leaving home. During the lesson, the battery ran out and she could not complete the activity.',question:'What caused Nadia to be unable to complete the activity?',options:['She forgot to charge the tablet.','The lesson ended early.','The activity was cancelled.','She lost her notebook.'],answer:'She forgot to charge the tablet.',explanation:'The uncharged battery led to the tablet running out.',difficulty:1},
{id:'P6-COMP-0018',type:'author_intent',skill:'supporting details',passage:'Walking or cycling for short journeys can reduce pollution. It can also give people more daily exercise. When possible, choose an active way to travel.',question:'Which detail supports the writer’s recommendation?',options:['Active travel can provide daily exercise.','Some journeys are long.','People own different vehicles.','Roads can be busy.'],answer:'Active travel can provide daily exercise.',explanation:'This detail directly supports choosing active travel.',difficulty:2},
{id:'P6-COMP-0019',type:'inference',skill:'emotion inference',passage:'After practising the piano piece every evening for two weeks, Mei finally played it without a mistake. She smiled and called her mother into the room.',question:'How was Mei most likely feeling?',options:['Proud','Confused','Frightened','Disappointed'],answer:'Proud',explanation:'Her successful performance and smile suggest pride.',difficulty:2},
{id:'P6-COMP-0020',type:'text_structure',skill:'paragraph purpose',passage:'Many people think that sleep is simply rest. However, during sleep the body and brain carry out important processes that support learning, memory and recovery.',question:'What is the second sentence mainly doing?',options:['Correcting a common misunderstanding','Giving instructions for sleeping','Describing a bedroom','Listing different bedtime routines'],answer:'Correcting a common misunderstanding',explanation:'However signals a contrast with the first sentence and introduces a correction.',difficulty:3}
];
